package escalation
import("context";"path/filepath";"testing";"time";"github.com/11DingKing/silvercare-coordination/internal/audit";"github.com/11DingKing/silvercare-coordination/internal/clock";"github.com/11DingKing/silvercare-coordination/internal/domain";"github.com/11DingKing/silvercare-coordination/internal/idgen";"github.com/11DingKing/silvercare-coordination/internal/outbox";storesqlite "github.com/11DingKing/silvercare-coordination/internal/store/sqlite")
func TestFailedEscalationResolutionPreservesAcknowledged(t *testing.T){ctx:=context.Background();now:=time.Date(2026,8,24,8,0,0,0,time.UTC);repo,e:=storesqlite.Open(ctx,filepath.Join(t.TempDir(),"e.db"));if e!=nil{t.Fatal(e)};defer repo.Close();repo.Migrate(ctx);repo.EnsureDistrict(ctx,nil,storesqlite.DistrictBudget{ID:"d",Name:"街道",Timezone:"Asia/Shanghai",MonthlyCents:1000000,Version:1,CreatedAt:now,UpdatedAt:now});exec:=func(q string,a ...any){if _,e:=repo.DB().ExecContext(ctx,q,a...);e!=nil{t.Fatal(e)}};ts:=now.Format(time.RFC3339Nano);exec(`INSERT INTO users(id,district_id,email,password_hash,display_name,role,active,created_at,updated_at) VALUES('u','d','u@e.test','h','u','coordinator',1,?,?)`,ts,ts);exec(`INSERT INTO residents(id,district_id,external_ref,full_name,birth_date,household_id,consent_status,version,created_at,updated_at) VALUES('r','d','ext','老人','1940-01-01','h','granted',1,?,?)`,ts,ts);exec(`INSERT INTO escalations(id,district_id,resident_id,visit_id,severity,status,summary,acknowledgement_due_at,acknowledged_by,acknowledged_at,resolved_at,version,created_at,updated_at) VALUES('e','d','r',NULL,'urgent','acknowledged','help',?, 'u', ?, NULL,2,?,?)`,now.Add(time.Hour).Format(time.RFC3339Nano),ts,ts,ts);exec(`CREATE TRIGGER reject BEFORE INSERT ON audit_events WHEN NEW.action='resolve' BEGIN SELECT RAISE(ABORT,'audit unavailable'); END`);s:=NewService(repo,&idgen.Sequence{},clock.NewFixed(now),audit.NewRecorder(repo),outbox.NewPublisher(repo,&idgen.Sequence{}));a:=domain.Actor{UserID:"u",DistrictID:"d",Role:domain.RoleCoordinator,RequestID:"req"};if _,e:=s.Resolve(ctx,a,"e",2);e==nil{t.Fatal("expected failure")};got,_:=repo.EscalationByID(ctx,nil,"e","d");if got.Status!=domain.EscalationAcknowledged||got.Version!=2{t.Errorf("state=%s/%d",got.Status,got.Version)};exec(`DROP TRIGGER reject`);if _,e:=s.Resolve(ctx,a,"e",2);e!=nil{t.Fatal(e)}}
